macro.command:
const pass = args[0]?.macroPass;
const cast = typeof workflow === "undefined" ? null : workflow;
const api = globalThis.dnd5eClasspack;
const DISEASES = [
  {
    "key": "blinding-sickness",
    "name": "失明症 Blinding Sickness",
    "img": "icons/skills/wounds/blood-cells-disease-green.webp",
    "statuses": [
      "blinded",
      "diseased"
    ],
    "changes": [
      [
        "system.abilities.wis.check.roll.mode",
        -1
      ],
      [
        "system.abilities.wis.save.roll.mode",
        -1
      ]
    ]
  },
  {
    "key": "filth-fever",
    "name": "腐热症 Filth Fever",
    "img": "icons/skills/wounds/blood-cells-disease-green.webp",
    "statuses": [
      "diseased"
    ],
    "changes": [
      [
        "system.abilities.str.check.roll.mode",
        -1
      ],
      [
        "system.abilities.str.save.roll.mode",
        -1
      ],
      [
        "system.abilities.str.attack.roll.mode",
        -1
      ]
    ]
  },
  {
    "key": "flesh-rot",
    "name": "烂肉症 Flesh Rot",
    "img": "icons/skills/wounds/blood-cells-disease-green.webp",
    "statuses": [
      "diseased"
    ],
    "changes": [
      [
        "system.abilities.cha.check.roll.mode",
        -1
      ],
      [
        "system.traits.dv.value",
        "ALL"
      ]
    ]
  },
  {
    "key": "mindfire",
    "name": "脑热症 Mindfire",
    "img": "icons/skills/wounds/blood-cells-disease-green.webp",
    "statuses": [
      "diseased"
    ],
    "changes": [
      [
        "system.abilities.int.check.roll.mode",
        -1
      ],
      [
        "system.abilities.int.save.roll.mode",
        -1
      ]
    ]
  },
  {
    "key": "seizure",
    "name": "癫痫症 Seizure",
    "img": "icons/skills/wounds/blood-cells-disease-green.webp",
    "statuses": [
      "diseased"
    ],
    "changes": [
      [
        "system.abilities.dex.save.roll.mode",
        -1
      ],
      [
        "system.abilities.dex.check.roll.mode",
        -1
      ],
      [
        "system.abilities.dex.attack.roll.mode",
        -1
      ]
    ]
  },
  {
    "key": "slimy-doom",
    "name": "恶心症 Slimy Doom",
    "img": "icons/skills/wounds/blood-cells-disease-green.webp",
    "statuses": [
      "diseased"
    ],
    "changes": [
      [
        "system.abilities.con.check.roll.mode",
        -1
      ],
      [
        "system.abilities.con.save.roll.mode",
        -1
      ]
    ]
  }
];
const stateOf = effect => effect.flags?.dnd5e_classpack?.contagion;
const live = effect => effect && effect.active !== false && !effect.disabled && !effect.isSuppressed;
const change = (key, value, type = "custom") => ({ key, value, type, phase: "initial", priority: 20,
  replacement: "", conditions: "{}" });
async function updateEffect(effect, updates) {
  if (effect.isOwner || game.user.isGM) return effect.update(updates);
  const result = await MidiQOL.socket().executeAsGM("updateEffects", {
    actorUuid: effect.parent.uuid, updates: [{ _id: effect.id, ...updates }]
  });
  if (result === false || result === "gmBlocked") throw new Error("无法更新疫病术效应");
}
async function selectDisease(effect) {
  if (!live(effect) || stateOf(effect)?.stage === "disease") return;
  const state = stateOf(effect) ?? {};
  const source = DAE.getEffectSource(effect);
  // 三次失败已使中毒结束。窗口关闭时仍保留待选择的疾病，不恢复豁免或删除效应。
  await updateEffect(effect, {
    name: "疫病术：待选择疾病", statuses: ["diseased"], "system.changes": [],
    "flags.dnd5e_classpack.contagion": { ...state, stage: "pending" },
    "flags.midi-qol.overtime.permanent": true
  });
  const templates = DISEASES;
  const caster = source.actorUuid ? await fromUuid(source.actorUuid) : null;
  const selected = await api.dialogUtils.selectDialog("疫病术", "", {
    label: "疾病", name: "disease", options: { options: templates.map(e => ({ value: e.key, label: e.name })) }
  }, { userId: caster ? api.firstOwner(caster, true) : game.user.id });
  const template = templates.find(e => e.key === selected);
  if (!template) return;
  const current = await fromUuid(effect.uuid);
  if (!live(current) || stateOf(current)?.stage !== "pending") return;
  const changes = template.changes.map(([key, value]) => change(key, value, "add"));
  if (selected === "slimy-doom") changes.push(change("flags.midi-qol.onUseMacroName", `ItemMacro.${source.itemUuid},isDamaged`));
  if (selected === "mindfire") {
    changes.push(change("flags.midi-qol.actions.reactionsMax", "0", "override"));
    changes.push(change("flags.midi-qol.OverTime", `turn=start, label=脑热症, macro=[postActiveEffects]ItemMacro.${source.itemUuid}, allowIncapacitated=true`));
  }
  await updateEffect(current, {
    name: template.name, img: template.img,
    statuses: [...new Set([...(template.statuses ?? []), "diseased"])],
    "system.magical": false,
    "system.changes": changes,
    "flags.dnd5e_classpack.contagion": { ...state, stage: "disease", diseaseId: selected }
    // 不修改 start 与 duration：疾病仍在原本七天期限结束时结束。
  });
}

if (args[0]?.reason === "replacementEffect") {
  const effect = args[0].effect;
  if (effect && (!stateOf(effect) || stateOf(effect).stage === "incubating")) await selectDisease(effect);
  return;
}
if (!cast || cast.aborted) return;

if (pass === "isDamaged") {
  const victim = args[0].actor;
  if (!victim) return;
  const diseases = Array.from(victim.appliedEffects ?? victim.effects).filter(e => live(e)
    && stateOf(e)?.stage === "disease" && stateOf(e).diseaseId === "slimy-doom");
  for (const disease of diseases) {
    const same = victim.effects.find(e => e.flags?.dnd5e_classpack?.contagionStun === disease.uuid);
    const ownTurn = game.combat?.started && game.combat.combatant?.actor?.uuid === victim.uuid;
    const duration = game.combat?.started
      ? { expiry: "targetEnd", value: ownTurn ? 1 : null, units: "rounds" }
      : { value: 12, units: "seconds", expiry: null };
    const data = {
      name: "恶心症：震慑", img: disease.img, type: "base", transfer: false, statuses: ["stunned"], duration,
      system: { magical: false, changes: [], origin: { ...disease.system.origin, effect: disease.uuid } },
      flags: { dnd5e: { dependentOn: disease.uuid }, dae: { expiryMode: "delete" },
        dnd5e_classpack: { contagionStun: disease.uuid } }
    };
    if (same) {
      await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: victim.uuid, effects: [same.id] });
    }
    await MidiQOL.socket().executeAsGM("createEffects", { actorUuid: victim.uuid, effects: [data] });
  }
  return;
}
if (pass !== "postActiveEffects") return;
const overtimeUuid = cast.workflowOptions?.overTimeEffectUuid;
if (overtimeUuid) {
  const effect = await fromUuid(overtimeUuid);
  if (!live(effect) || stateOf(effect)?.diseaseId !== "mindfire") return;
  if (cast._classpackMindfireDone) return;
  cast._classpackMindfireDone = true;
  const roll = await new Roll("1d10").evaluate();
  const action = roll.total === 1 ? "沿随机方向用尽移动力，本回合不执行动作。"
    : roll.total <= 6 ? "本回合不移动，也不执行动作。"
    : roll.total <= 8 ? "攻击触及内随机生物一次；没有可攻击生物则不执行动作。"
    : "本回合可以正常行动。";
  await roll.toMessage({ speaker: ChatMessage.getSpeaker({ actor: effect.parent }),
    flavor: `脑热症：困惑术表。${action}` });
  return;
}
